import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as i,a as o}from"./chunks/M-BT-BK.DTMS2NtJ.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as a,o as l,c as p,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const B=JSON.parse('{"title":"Transmetteur Libre","description":"","frontmatter":{"source_hash":"dc2943a1ef","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/install/libreBT.md","filePath":"fr/install/libreBT.md"}'),d={name:"fr/install/libreBT.md"};function u(m,s,v,g,h,b){return l(),p("div",null,[...s[0]||(s[0]=[c('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Libre Bluetooth</p></div><p>De nombreux transmetteurs NFC vers Bluetooth pour capteurs Libre sont disponibles sur le marché.</p><p>Le projet d&#39;origine a été développé par Joern : <a href="https://github.com/JoernL/LimiTTer" target="_blank" rel="noreferrer">LimiTTer</a>. Retenez ce nom, car il apparaît comme nom de transmetteur par défaut lorsque l&#39;appareil réel n&#39;est pas identifié. À moins que vous ayez réellement un LimiTTer (ou que vous connectiez directement un Libre 2), voir ce nom signifie que votre transmetteur n&#39;est pas connecté à xDrip.</p><p>xDrip prend en charge certains d&#39;entre eux pour certains capteurs.<br><strong>Les Libre H et Libre 2/2+ US/CA/AUS ne sont pas pris en charge.</strong><br> Vous pouvez utiliser Diabox ou Juggluco en mode <a href="./libre2patch.html">Libre (patched app)</a>.</p><p>Voici ci-dessous un tableau de compatibilité des transmetteurs pris en charge ; pour les capteurs compatibles, la version <strong>minimale</strong> du firmware est indiquée.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Transmetteur</th><th style="text-align:center;">- Libre 1 / Pro -</th><th style="text-align:center;">- 14 jours US -</th><th style="text-align:center;">- Libre 2/2+ EU -</th></tr></thead><tbody><tr><td style="text-align:center;">MiaoMiao</td><td style="text-align:center;"><code>Oui</code></td><td style="text-align:center;"><code>39*</code></td><td style="text-align:center;"><code>39*</code></td></tr><tr><td style="text-align:center;">MiaoMiao 2</td><td style="text-align:center;"><code>Oui</code></td><td style="text-align:center;"><code>7*</code></td><td style="text-align:center;"><code>7*</code></td></tr><tr><td style="text-align:center;">MiaoMiao 3</td><td style="text-align:center;"><code>Oui</code></td><td style="text-align:center;"><code>3A*</code></td><td style="text-align:center;"><code>3A*</code></td></tr><tr><td style="text-align:center;">Atom</td><td style="text-align:center;"><code>Oui</code></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p><em>Remarque :</em><br><em><code>*</code> <a href="./../use/OOP.html">module externe OOP nécessaire</a></em></p><br><h2 id="bridge-settings" tabindex="-1">Paramètres du transmetteur <a class="header-anchor" href="#bridge-settings" aria-label="Permalink to &quot;Paramètres du transmetteur {#bridge-settings}&quot;">​</a></h2><p>Si ce n&#39;est pas encore fait, <a href="./install.html#make-sure-xdrip-will-not-be-put-to-sleep">vérifiez que xDrip ne sera pas mis en veille</a>.</p><p>Avant d&#39;essayer de connecter votre transmetteur, vérifiez que vos paramètres sont corrects afin d&#39;éviter des déconnexions fréquentes.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Paramètres<br>  Paramètres moins courants<br>   Paramètres Bluetooth</p></div><p>Pour commencer, utilisez les paramètres indiqués ci-dessous.</p><p>Le Bluetooth doit être allumé. <strong>Activez</strong> <code>Activer le Bluetooth</code>.</p><div class="admonition xdripitem"><p class="admonition-title">Activer le Bluetooth <span class="symbol"><img src="'+r+'" style="zoom:75%;"></span></p><p> Activer automatiquement bluetooth s&#39;il est éteint lorsqu&#39;on tente de se connecter à un périphérique bluetooth</p></div><p><strong>Activez</strong> le garde-fou, mais lisez l&#39;information ci-dessous.</p><div class="admonition xdripitem"><p class="admonition-title">Garde-fou Bluetooth <span class="symbol"><img src="'+r+'" style="zoom:75%;"></span></p><p> Réinitialiser Bluetooth en le désactivant puis réactivant si nous n’obtenons rien pendant 20 minutes</p></div><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Attention : le Garde-fou Bluetooth éteint puis rallume le Bluetooth du téléphone, ce qui provoque une déconnexion Bluetooth temporaire de tous les appareils connectés. Vous voudrez peut-être désactiver cette fonction si vous utilisez AAPS et que votre transmetteur ou votre pompe ne rétablit pas automatiquement la connexion Bluetooth.</p></div><p><strong>Désactivez</strong> Fermer GATT.</p><div class="admonition xdripitem"><p class="admonition-title">Fermer GATT sur déconnexion BLE <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Si le garde-fou Bluetooth s&#39;active souvent alors vous pouvez essayer de décocher cette option pour voir si ça aide</p></div><p>Si votre transmetteur perd la connexion et qu&#39;un scan Bluetooth permet de la rétablir, vous pouvez essayer d&#39;activer <code>Utiliser le scan</code>. Laissez-le <strong>désactivé</strong> pour commencer.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser le scan <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Scanner avant de se connecter sur xBridge et Bluetooth Libre</p></div><p>Sur les téléphones Samsung et de nombreux téléphones chinois, vous <strong>devez désactiver <code>Faire confiance à Auto-Connect</code></strong> ! Si votre téléphone perd la connexion, <strong>désactivez-le</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Faire confiance à Auto-Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser et faire confiance à la fonctionnalité de connexion auto Bluetooth d&#39;Android</p></div><p>À partir d&#39;Android 8, vous pouvez activer <code>Utiliser les scans en arrière-plan</code>. Si vous perdez la connexion, <strong>laissez-le désactivé</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les scans en arrière-plan <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser la fonction de scan en arrière-plan d&#39;Android 8+</p></div><p>Laissez les deux options ci-dessous <strong>désactivées</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Wakelocks Bluetooth <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Anciens wakelocks Bluetooth qui peuvent drainer la batterie un peu plus, mais pourraient être nécessaire pour la réception bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Redémarrer le Bluetooth en permanence <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Réinitialiser le Bluetooth en le désactivant en en le réactivant après quelques minutes ! À sélectionner uniquement pour test. Cela peut perturber les autres utilisations du Bluetooth.</p></div><p>Si votre transmetteur est un Transmitter_T ou un Droplet, activez cette option ; sinon laissez-la <strong>désactivée</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Support de Transmitter (PL) <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Support expérimental du périphérique &#39;Transmitter&#39; de @FPV-UAV - test uniquement</p></div><p>En cas de pertes de connexion, vous pouvez <strong>activer</strong> le mode de sondage. Il ne fait rien d&#39;utile en soi, mais garde le Bluetooth du téléphone éveillé.</p><div class="admonition xdripitem"><p class="admonition-title">Mode de sondage xBridge+ <span class="symbol"><img src="'+r+'" style="zoom:75%;"></span></p><p> Support expérimental pour la fonction de sondage xBridge+</p></div><p>Si votre transmetteur est un ancien BluCon compatible, vous pouvez activer cette option ; si vous avez plusieurs demandes d&#39;appairage par jour, laissez-la <strong>désactivée</strong>.<br><em>Remarque : seul le BluCon s&#39;appaire (bond) avec Android, les autres transmetteurs non.</em></p><div class="admonition xdripitem"><p class="admonition-title">Permettre la dissociation du BluCon <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Disponible uniquement pour les téléphones qui supportent l&#39;association automatique</p></div><br><p>Redémarrez votre téléphone pour vous assurer que tous les paramètres sont pris en compte.</p><br><h2 id="connect-bluetooth-bridge" tabindex="-1">Connecter le transmetteur Bluetooth <a class="header-anchor" href="#connect-bluetooth-bridge" aria-label="Permalink to &quot;Connecter le transmetteur Bluetooth {#connect-bluetooth-bridge}&quot;">​</a></h2><p>Vérifiez que votre transmetteur n&#39;est connecté à rien d&#39;autre : ni à un autre appareil, ni à une autre application.<br> Lancez un scan Bluetooth.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Scan Bluetooth</p></div><p>Si le scan ne démarre pas automatiquement, sélectionnez <code>BALAYAGE</code>.</p><img src="'+i+'" style="zoom:75%;"><p>Si votre transmetteur n&#39;apparaît pas, vérifiez qu&#39;il est complètement chargé (ou qu&#39;il a une pile neuve) et réinitialisez-le.</p><p>Une fois visible, sélectionnez-le.</p><p>Si votre transmetteur est un BluCon, saisissez le code inscrit sur le côté.</p><img src="'+o+'" style="zoom:55%;"><p>Positionnez-le correctement sur votre capteur. Certains transmetteurs tolèrent très peu d&#39;écart d&#39;angle et de distance par rapport au capteur.</p><div class="info custom-block"><p class="custom-block-title">Module externe</p><p>Si votre capteur nécessite un <a href="./../use/OOP.html">algorithme hors processus (OOP)</a>, assurez-vous qu&#39;il est installé dès maintenant.</p></div><br><p>Passez ensuite à <a href="./../use/startsensor.html#libre">Démarrer le capteur</a></p><h2 id="stop-libre-sensor" tabindex="-1">Arrêter le capteur Libre <a class="header-anchor" href="#stop-libre-sensor" aria-label="Permalink to &quot;Arrêter le capteur Libre {#stop-libre-sensor}&quot;">​</a></h2><p>xDrip ne peut pas arrêter physiquement un capteur Libre ; celui-ci s&#39;arrête de lui-même après 14 jours et 12 heures et continue d&#39;afficher la dernière valeur.</p><p>Néanmoins, lors d&#39;un changement de capteur, il est vivement recommandé d&#39;informer xDrip du changement en arrêtant le capteur.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Arrêter le capteur</p></div><p>Confirmez que vous voulez vraiment arrêter le capteur.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;"> Arrêt du capteur <span class="symbol"></span></p><p> N&#39;arrêtez votre capteur que lorsque vous planifiez de l&#39;enlever, sinon laissez fonctionner!</p><p>       <span style="background-color:white;color:black;"> ARRÊTER LE CAPTEUR </span></p></div><p>Cela réinitialise toutes les calibrations et permet à xDrip de démarrer un nouveau capteur.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',60)])])}const A=a(d,[["render",u]]);export{B as __pageData,A as default};
